<script>
(()=>{const challengeUrl=@json(route('user.coin-vendor.challenge')), uploadUrl=@json(route('user.coin-vendor.liveness.record')), csrf=@json(csrf_token());let stream,recorder,ch,parts=[],started=0,token=null,challengeId=null;
 const $=id=>document.getElementById(id),status=$('camera-status'),help=$('camera-help');if(!$('camera-start'))return;
 $('camera-start').onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:true});$('vendor-preview').srcObject=stream;const r=await fetch(challengeUrl,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'}});if(!r.ok)throw new Error('Save your ID details before starting the camera check.');ch=await r.json();token=ch.token;challengeId=ch.challenge_id;$('vendor-code').textContent=ch.code;$('camera-record').disabled=false;status.textContent='Camera ready. Code expires in five minutes.'}catch(e){help.textContent='Camera or microphone access failed. Check browser permissions, use HTTPS, or continue on another device. '+e.message;status.textContent='Camera check was not started.'}};
 $('camera-record').onclick=()=>{const types=['video/mp4;codecs="avc1.42E01E,mp4a.40.2"','video/mp4','video/webm;codecs=vp8,opus','video/webm'];const mime=types.find(x=>window.MediaRecorder?.isTypeSupported(x));if(!mime){help.textContent='This browser does not support a compatible in-page camera recording. Try current iOS Safari or Android Chrome on another device.';return}parts=[];recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:800000,audioBitsPerSecond:64000});recorder.ondataavailable=e=>e.data.size&&parts.push(e.data);recorder.onstop=()=>{$('camera-record').disabled=false;$('camera-submit').disabled=false;$('vendor-playback').src=URL.createObjectURL(new Blob(parts,{type:mime}));$('vendor-playback').hidden=false;status.textContent='Recording ready. Review it, then save securely.'};recorder.start(500);started=Date.now();$('camera-record').disabled=true;$('camera-submit').disabled=true;status.textContent='Recording… say your legal name and the code.';setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},15000);setTimeout(()=>{if(recorder?.state==='recording'&&Date.now()-started>=8000)recorder.stop()},8000)};
 $('camera-submit').onclick=async()=>{const duration=Date.now()-started;if(duration<8000||duration>16000){status.textContent='Record between 8 and 15 seconds, then try again.';return}const blob=new Blob(parts,{type:parts[0]?.type||'video/webm'});if(blob.size>6*1024*1024){status.textContent='Recording is over 6 MB. Record in a quieter, well-lit place or use another device.';return}const fd=new FormData();fd.append('video',blob,blob.type.includes('mp4')?'selfie.mp4':'selfie.webm');fd.append('duration_ms',duration);fd.append('liveness_token',token);fd.append('challenge_id',challengeId);try{const res=await fetch(uploadUrl,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:fd});const data=await res.json();if(!res.ok)throw new Error(data.message||'Could not save the recording.');status.textContent=data.message;setTimeout(()=>location.reload(),700)}catch(e){status.textContent=e.message}};
 addEventListener('pagehide',()=>stream?.getTracks().forEach(t=>t.stop()));})();
</script>
